import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    parents = [0] * (n + 1)
    adj = [[] for _ in range(n + 1)]
    roots = []

    for i in range(1, n + 1):
        p = int(next(iterator))
        parents[i] = p
        if p != 0:
            adj[p].append(i)
        else:
            roots.append(i)

    m = int(next(iterator))
    queries = []
    for _ in range(m):
        v = int(next(iterator))
        p = int(next(iterator))
        queries.append((v, p))

    depth = [0] * (n + 1)
    up = [[0] * (n + 1) for _ in range(20)]

    def dfs(u, d):
        depth[u] = d
        up[0][u] = parents[u]
        for k in range(1, 20):
            if up[k-1][u] != 0:
                up[k][u] = up[k-1][up[k-1][u]]
            else:
                up[k][u] = 0
        for v in adj[u]:
            dfs(v, d + 1)

    for r in roots:
        dfs(r, 0)

    def get_kth_ancestor(node, k):
        curr = node
        bit = 0
        while k > 0:
            if k & 1:
                curr = up[bit][curr]
                if curr == 0:
                    break
            k >>= 1
            bit += 1
        return curr

    timer = 0
    tin = [0] * (n + 1)
    tout = [0] * (n + 1)

    def dfs_euler(u):
        nonlocal timer
        timer += 1
        tin[u] = timer
        for v in adj[u]:
            dfs_euler(v)
        tout[u] = timer

    for r in roots:
        dfs_euler(r)

    def is_ancestor(u, v):
        return tin[u] <= tin[v] and tout[u] >= tout[v]

    results = []
    for v, p in queries:
        ancestor = get_kth_ancestor(v, p)
        if ancestor == 0:
            results.append(0)
            continue

        target_depth = depth[v] - p
        count = 0

        def count_descendants(node, target_d):
            nonlocal count
            if depth[node] == target_d:
                if node != v:
                    count += 1
                return
            if depth[node] > target_d:
                return
            for child in adj[node]:
                count_descendants(child, target_d)

        count_descendants(ancestor, target_depth)
        results.append(count)

    print(" ".join(map(str, results)))

if __name__ == "__main__":
    main()
